import pickle


class CollectorConfigurationData:
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self._mapping = {}
        self._collector_configurations = []
        self._last_configurations_dict = None
        self._last_sorted_configurations = None

    @property
    def collector_configurations(self):
        """
        Return the collector configurations.

        Don't use this property to modify the collector configurations.

        :return: collector configurations
        :rtype: list(dict)
        """
        return self._collector_configurations

    @property
    def mapping(self):
        """
        Return the mapping of log type and network element to collector configuration.

        :return:
            mapping, where the key is a tuple of log type and network element and the value
            is the collector configuration
        :rtype: dict[tuple(str, str), dict]
        """
        return self._mapping

    @property
    def collector_configurations_dict(self):
        if self._last_configurations_dict is None:
            self._last_configurations_dict = {}
            for collector_configuration in self._collector_configurations:
                collector_name = collector_configuration["name"]
                if collector_name in self._last_configurations_dict:
                    raise AssertionError(
                        f"Collector {collector_name} occurs multiple times "
                        f"in {self._collector_configurations}!")
                self._last_configurations_dict[collector_name] = collector_configuration
        return self._last_configurations_dict

    @property
    def sorted_collector_configurations(self):
        if self._last_sorted_configurations is None:
            self._last_sorted_configurations = [
                collector_configuration
                for collector_configuration in self._collector_configurations
                if not any(attr_name in collector_configuration for attr_name in ("members", "collector", "tool"))]
            while len(self._last_sorted_configurations) < len(self._collector_configurations):
                new_collector_configurations = [
                    collector_configuration
                    for collector_configuration in self._collector_configurations
                    if collector_configuration not in self._last_sorted_configurations and all(
                        child in self._last_sorted_configurations
                        for child in self._get_child_configurations(collector_configuration))]
                self._last_sorted_configurations.extend(new_collector_configurations)
        return self._last_sorted_configurations

    def _get_child_configurations(self, collector_configuration):
        collector_configurations_dict = self.collector_configurations_dict
        child_configurations = []
        if "members" in collector_configuration:
            child_configurations.extend(
                collector_configurations_dict[child_configuration_name]
                for child_configuration_name in collector_configuration["members"])
        for child_type in ("collector", "tool"):
            if child_type in collector_configuration:
                child_configuration_name = collector_configuration[child_type]
                child_configurations.append(
                    collector_configurations_dict[child_configuration_name])
        return child_configurations

    def dump(self, stream):
        pickle.dump(
            {
                'mapping': self._mapping,
                'configurations': self._collector_configurations},
            stream)

    def load(self, stream):
        data = pickle.load(stream)
        self._mapping = data['mapping']
        self._collector_configurations = data['configurations']

    def append(self, collector_configuration):
        self._last_configurations_dict = None
        self._last_sorted_configurations = None
        self._collector_configurations.append(collector_configuration)

    def update_configurations(self, collector_configurations):
        self._last_configurations_dict = None
        self._last_sorted_configurations = None
        collector_configurations_dict = self.collector_configurations_dict
        for collector_configuration in collector_configurations:
            collector_name = collector_configuration['name']
            if collector_name in collector_configurations_dict \
                    and collector_configuration['type'] == 'group':
                collector_configurations_dict[collector_name]['members'] += \
                    collector_configuration['members']
                collector_configurations_dict[collector_name]['members'] = list(set(
                    collector_configurations_dict[collector_name]['members']
                ))
            else:
                collector_configurations_dict[collector_name] = collector_configuration
        self._collector_configurations = list(collector_configurations_dict.values())

    def update_mapping(self, collector_mapping):
        self._mapping.update(collector_mapping)

    def add_mapping_entry(self, log_type, network_element, collector_configuration):
        self._mapping[(log_type, network_element)] = collector_configuration

    def update(self, collector_configuration_data):
        self.update_configurations(collector_configuration_data.collector_configurations)
        self.update_mapping(collector_configuration_data.mapping)

    def get_configuration_by_log_type_and_network_element(self, log_type, network_element):
        return self._mapping.get((log_type.lower(), network_element))

    def get_configuration_by_collector_name(self, collector_name):
        return self.collector_configurations_dict[collector_name]

    def find_ancestor_group_names(self, collector_name):
        parent_group_names = self.find_parent_group_names(collector_name)
        if len(parent_group_names) > 1:
            raise AssertionError(f"Collector {collector_name} is member of multiple groups: {parent_group_names}")
        if len(parent_group_names) == 0:
            return []
        return self.find_ancestor_group_names(parent_group_names) + parent_group_names

    def find_parent_group_names(self, collector_name):
        return [
            collector_configuration["name"]
            for collector_configuration in self._collector_configurations
            if collector_configuration["type"] == "group"
            and collector_name in collector_configuration["members"]]

    def find_parent_groups(self, collector_name):
        return [
            collector_configuration
            for collector_configuration in self._collector_configurations
            if collector_configuration["type"] == "group"
            and collector_name in collector_configuration["members"]]

    def find_collectors(self, collector_type):
        return [
            collector
            for collector in self._collector_configurations
            if collector['type'] == collector_type]
